no_retry.retrying.py:
def retry(operation, attempts=3):
    if attempts < 1:
        raise ValueError("attempts must be positive")
    return operation()

swallow_error.retrying.py:
def retry(operation, attempts=3):
    if attempts < 1:
        raise ValueError("attempts must be positive")
    for index in range(attempts):
        try:
            return operation()
        except RuntimeError:
            if index == attempts - 1:
                return None

extra_attempt.retrying.py:
def retry(operation, attempts=3):
    if attempts < 1:
        raise ValueError("attempts must be positive")
    for index in range(attempts + 1):
        try:
            return operation()
        except RuntimeError:
            if index == attempts:
                raise

